import datetime
try:
    if isinstance(result, dict):
        result.pop('header', None)
        d = result.get('data')
        if isinstance(d, dict) and isinstance(d.get('products'), list):
            try:
                today = datetime.date.fromisoformat(str(vars.get('now'))[:10])
            except Exception:
                today = datetime.date(2026, 10, 14)
            hol = [datetime.date(2026, 10, 16), datetime.date(2026, 12, 25), datetime.date(2026, 12, 26), datetime.date(2027, 1, 1)]
            ends = []
            x = today
            while len(ends) < 3:
                x = x + datetime.timedelta(days=1)
                if x.weekday() < 5 and x not in hol:
                    ends.append(x.isoformat())
            for p in d['products']:
                if not isinstance(p, dict):
                    continue
                pct = 40 if p.get('type') == 'credit_card' else 25 if p.get('type') == 'personal_loan' else 0
                if not pct:
                    p['rule'] = 'car loan: no promise, no floor, no note. Transfer to queue restructuring.'
                    continue
                c = int(round(float(p.get('past_due') or 0) * 100))
                p['floor'] = (c * pct + 50) // 100 / 100.0
                late = int(p.get('days_late') or 0) > 10
                p['band'] = 'late' if late else 'early'
                p['deadline'] = ends[1] if late else ends[2]
                p['attempts'] = 2 if late else 1
            d['what_to_do_next'] = 'State every late product in this order. Then ask once whether the customer can pay the full past_due of all non-car products today.'
except Exception:
    pass

